# Integrate the separate, fully scoped team read without attributing it to this agent.
independent_file=ROOT/'work/invariants_arithmetic/cdp_A5_independent_audit.json'
if independent_file.exists():
    for record in json.loads(independent_file.read_text()):
        sid=record['source_id']; r=by_id[sid]; check=record['own_check']
        assert r['proof_sha256']==record['proof_sha256'], (sid,'source proof changed')
        r['own_check']=(check['checker']+', effort '+check['effort']+', '+check['date']+
            '; independent team reader /root/invariants_arithmetic: '+check['details'])
        r['check_outcome']=record['check_outcome']
        r['depends_on']='; '.join(record['depends_on'])
        r['credit_checks']='Complete scoped four-baseline comparison: deliverables/work/invariants_arithmetic/cdp_A5_credit_comparison.json#'+sid+'; actual searches retained in cdp_A5_credit_search.json.'
        r['remarks']='Full independent event and source/program locators: deliverables/work/invariants_arithmetic/cdp_A5_independent_audit.json#'+sid+'. '+check['source_candidate_comparison']

root_file=ROOT/'work/root/cdp_reserved_full_checks.json'
if root_file.exists():
    for record in json.loads(root_file.read_text()):
        sid=record['source_id']; r=by_id[sid]
        assert r['proof_sha256']==record['full_block_sha256'], (sid,'source proof changed')
        r['own_check']='Independent team reader /root: '+record['own_check']
        r['check_outcome']=record['check_outcome']
        r['credit_checks']='Complete scoped comparison and actual searches: deliverables/work/root/cdp_reserved_credit_comparison.json#'+sid+'; deliverables/work/root/cdp_reserved_credit_searches.json.'
        r['remarks']='Full independent event, source ranges, included inputs and program locators: deliverables/work/root/cdp_reserved_full_checks.json#'+sid+'. Ingestion compares the exact full statement/proof SHA-256.'

reviews={}
def review(ids,info):
    for sid in ids.split(','): reviews.setdefault(sid,[]).append(info)
review('A.5.2,A.5.3,A.5.4,A.5.6,A.5.9,A.5.11,A.5.12,A.5.13','Claude Fable 5.2 (Anthropic), effort max, 16 November 2026; reviews/S6_FINAL_INTAKE_20261116/EXPERT_POSITION.md:77–91; followed proof, no gap found; expressly not a review of UN1–86.')
review('A.4.9,A.5.7,A.5.8','Claude Fable 5.2 (Anthropic), effort max, 16 November 2026; reviews/S6_FINAL_INTAKE_20261116/RESPONSE_EXPERT.md:67–84; full local proof followed, with listed dependencies outstanding.')
review('A.5.10','Claude Fable 5.2 (Anthropic), effort max, 16 November 2026; reviews/S6_FINAL_INTAKE_20261116/RESPONSE_EXPERT.md:67–84; recomputed Chern identity and two intersection identities only; local epsilon,r_i,2R<=V accepted as stated.')
